package com.investinator.monitoring;
import static com.investinator.domain.Json.*;
import com.investinator.domain.Json;
import com.investinator.domain.Contracts.*;
import com.investinator.persistence.*;
import com.investinator.workflows.WorkflowService;
import com.investinator.correlation.*;
import com.investinator.api.ApiFailure;
import com.investinator.agent.DeterministicInvestigator;
import com.investinator.chat.ChatService;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.core.env.Environment;
import java.time.*;
import java.util.*;
@Service @ConditionalOnProperty(name="investinator.persistence.enabled",havingValue="true")
public class MonitoringService {
    public final Store db;private final WorkflowService workflows;private final CorrelationService correlations;private final DetectionRules rules;private final Environment env;private final ChatService chat;
    public MonitoringService(Store db,WorkflowService w,CorrelationService c,DetectionRules r,Environment env,ChatService chat){this.db=db;workflows=w;correlations=c;rules=r;this.env=env;this.chat=chat;}
    public boolean enabled(){return env.getProperty("investinator.monitor.enabled",Boolean.class,false)&&env.getProperty("investinator.demo-mode",Boolean.class,true);}
    private void requireEnabled(){if(!enabled())throw new ApiFailure(503,"Monitoring is opt-in and demo-scoped");}
    public Map<String,Object> status(String tenant){var rows=db.jdbc.queryForList("select paused from monitor_controls where tenant_id=?",Boolean.class,tenant);return obj("enabled",enabled(),"paused",rows.isEmpty()||rows.getFirst(),"source_mode","SIMULATED_REPLAY_WITH_LIVE_HEALTH_SAMPLES","rules_version",1,"queued",db.jdbc.queryForObject("select count(*) from monitor_events where tenant_id=? and state='QUEUED'",Long.class,tenant),"offset",db.jdbc.queryForList("select last_seq from monitor_offsets where tenant_id=?",Long.class,tenant),"incidents",db.jdbc.queryForList("select id,lifecycle,graph_id,cluster_id,source_mode,active from monitor_incidents where tenant_id=? order by updated_at desc limit 100",tenant),"settings",settings(tenant),"outbox",db.jdbc.queryForList("select kind,state,count(*) as count from monitor_outbox where tenant_id=? group by kind,state",tenant));}
    public Map<String,Object> control(String tenant,boolean paused){requireEnabled();return db.write(tenant,()->{db.jdbc.update("insert into monitor_controls(tenant_id,paused) values(?,?) on conflict(tenant_id) do update set paused=excluded.paused,updated_at=now()",tenant,paused);workflows.audit(tenant,"monitor_control",null,"demo.monitor_operator",obj("paused",paused));return status(tenant);});}
    public record Settings(int cadence_seconds,int suppress_seconds,List<String> disabled_rules){}
    public Map<String,Object> settings(String tenant){var rows=db.jdbc.queryForList("select tick_seconds,disabled_rules::text,suppressed_until from monitor_controls where tenant_id=?",tenant);if(rows.isEmpty())return obj("cadence_seconds",5,"disabled_rules",List.of(),"suppressed_until",null);var row=rows.getFirst();return obj("cadence_seconds",row.get("tick_seconds"),"disabled_rules",Json.decode(row.get("disabled_rules").toString()),"suppressed_until",row.get("suppressed_until")==null?null:((java.sql.Timestamp)row.get("suppressed_until")).toInstant().toString());}
    public Map<String,Object> configure(String tenant,Settings input){requireEnabled();if(input.cadence_seconds()<5||input.cadence_seconds()>300||input.suppress_seconds()<0||input.suppress_seconds()>3600||input.disabled_rules()==null||input.disabled_rules().size()>15)throw new ApiFailure(422,"Monitoring override outside allowed bounds");input.disabled_rules().forEach(rules::rule);return db.write(tenant,()->{db.jdbc.update("insert into monitor_controls(tenant_id) values(?) on conflict do nothing",tenant);db.jdbc.update("update monitor_controls set tick_seconds=?,disabled_rules=?::jsonb,suppressed_until=case when ?=0 then null else now()+(? * interval '1 second') end,next_tick_at=now(),updated_at=now() where tenant_id=?",input.cadence_seconds(),encode(input.disabled_rules().stream().distinct().sorted().toList()),input.suppress_seconds(),input.suppress_seconds(),tenant);workflows.audit(tenant,"monitor_settings",null,"demo.monitor_operator",obj("cadence_seconds",input.cadence_seconds(),"disabled_rules",input.disabled_rules(),"suppression_seconds",input.suppress_seconds()));return status(tenant);});}
    public boolean claimScheduledTick(String tenant){return db.write(tenant,()->db.jdbc.update("update monitor_controls set next_tick_at=now()+(tick_seconds * interval '1 second') where tenant_id=? and not paused and next_tick_at<=now()",tenant)==1);}
    private boolean suppressed(String tenant){return db.jdbc.queryForObject("select exists(select 1 from monitor_controls where tenant_id=? and suppressed_until>now())",Boolean.class,tenant);}
    private Object sorted(Object value){if(value instanceof Map<?,?> map){var out=new TreeMap<String,Object>();map.forEach((k,v)->out.put(k.toString(),sorted(v)));return out;}if(value instanceof List<?> list)return list.stream().map(this::sorted).toList();return value;}
    public String hash(Object value){return DeterministicInvestigator.digest(encode(sorted(Json.decode(encode(value)))));}
    public Map<String,Object> accept(String tenant,MonitoringContracts.SignalReceived event){requireEnabled();if(!tenant.equals(event.tenant_id())||!event.source_mode().equals("SIMULATED"))throw new ApiFailure(403,"Only owned tenant SIMULATED replay is accepted");var graph=validate(event);String hash=hash(event);return db.write(tenant,()->{var old=db.jdbc.queryForList("select digest,state from monitor_events where tenant_id=? and event_id=?",tenant,event.event_id());if(!old.isEmpty()){if(!old.getFirst().get("digest").equals(hash))throw new ApiFailure(409,"Event identity is immutable");return obj("duplicate",true,"state",old.getFirst().get("state"));}if(db.jdbc.queryForObject("select count(*) from monitor_events where tenant_id=? and state='QUEUED'",Integer.class,tenant)>=1000)throw new ApiFailure(429,"Monitoring queue full; retain source checkpoint and retry");rules.rule(event.rule_id());db.jdbc.update("insert into monitor_events(tenant_id,event_id,digest,payload) values(?,?,?,?::jsonb)",tenant,event.event_id(),hash,encode(event));return obj("duplicate",false,"state","QUEUED","graph_revision",graph.revision());});}
    private DependencyGraph validate(MonitoringContracts.SignalReceived e){var graph=correlations.graph(e.tenant_id(),e.graph_id(),e.graph_revision());if(!graph.source_mode().equals(e.source_mode())||graph.nodes().stream().noneMatch(n->n.id().equals(e.resource())))throw new ApiFailure(422,"Unverified source/resource graph scope");return graph;}
    public Object dryRun(MonitoringContracts.SignalReceived e){var graph=validate(e);return obj("rules_version",1,"verdict",rules.evaluate(e,graph.metadata_mode()),"signal",rules.rule(e.rule_id()).signal(),"side_effects",false);}
    private String scope(MonitoringContracts.SignalReceived e,DependencyGraph graph){var component=new TreeSet<String>();component.add(e.resource());boolean changed;do{changed=false;for(var edge:graph.at(Instant.parse(e.observed_at())))if(component.contains(edge.from())||component.contains(edge.to())){changed|=component.add(edge.from());changed|=component.add(edge.to());}}while(changed);return hash(List.of(e.tenant_id(),e.environment(),e.cluster_id(),e.source_mode(),e.graph_id(),component.first(),"availability"));}
    public int tick(String tenant){requireEnabled();boolean paused=(Boolean)status(tenant).get("paused");if(paused)return 0;int count=0;for(int n=0;n<100;n++){boolean worked=db.write(tenant,()->{var controls=db.jdbc.queryForList("select paused from monitor_controls where tenant_id=?",Boolean.class,tenant);if(controls.isEmpty()||controls.getFirst())return false;var rows=db.jdbc.queryForList("select seq,payload::text from monitor_events where tenant_id=? and state='QUEUED' order by seq limit 1 for update",tenant);if(rows.isEmpty())return false;var row=rows.getFirst();long seq=((Number)row.get("seq")).longValue();var event=Json.decode(row.get("payload").toString(),MonitoringContracts.SignalReceived.class);process(tenant,seq,event);db.jdbc.update("insert into monitor_offsets(tenant_id,last_seq) values(?,?) on conflict(tenant_id) do update set last_seq=greatest(monitor_offsets.last_seq,excluded.last_seq)",tenant,seq);return true;});if(!worked)break;count++;}dispatch(tenant);return count;}
    private void mark(String tenant,long seq,String state,String incident){db.jdbc.update("update monitor_events set state=?,incident_id=? where tenant_id=? and seq=?",state,incident,tenant,seq);}
    private void process(String tenant,long seq,MonitoringContracts.SignalReceived e){
        if(((List<?>)settings(tenant).get("disabled_rules")).contains(e.rule_id())){mark(tenant,seq,"RULE_DISABLED",null);return;}Instant time=Instant.parse(e.observed_at()),now=Instant.now();if(time.isAfter(now.plusSeconds(30))||time.isBefore(now.minusSeconds(14400))){mark(tenant,seq,"STALE_OR_FUTURE",null);return;}var graph=validate(e);var verdict=rules.evaluate(e,graph.metadata_mode());if(verdict==DetectionRules.Verdict.UNKNOWN||verdict==DetectionRules.Verdict.INCOMPATIBLE){mark(tenant,seq,verdict.name(),null);return;}
        String scope=scope(e,graph);var streak=db.jdbc.queryForList("select bad_count,last_event from monitor_streaks where tenant_id=? and scope_key=? and rule_id=? and resource=?",tenant,scope,e.rule_id(),e.resource());int bad=streak.isEmpty()?0:((Number)streak.getFirst().get("bad_count")).intValue();boolean newer=streak.isEmpty()||!time.isBefore(((java.sql.Timestamp)streak.getFirst().get("last_event")).toInstant());if(newer){boolean continuous=streak.isEmpty()||Duration.between(((java.sql.Timestamp)streak.getFirst().get("last_event")).toInstant(),time).toSeconds()<=rules.cooldownSeconds();bad=verdict==DetectionRules.Verdict.ABNORMAL?(continuous?Math.min(rules.hysteresis(),bad+1):1):0;db.jdbc.update("insert into monitor_streaks(tenant_id,scope_key,rule_id,resource,bad_count,last_event) values(?,?,?,?,?,?) on conflict(tenant_id,scope_key,rule_id,resource) do update set bad_count=excluded.bad_count,last_event=excluded.last_event",tenant,scope,e.rule_id(),e.resource(),bad,java.sql.Timestamp.from(time));}
        var active=db.jdbc.queryForList("select id,graph_revision from monitor_incidents where tenant_id=? and scope_key=? and active",tenant,scope);String incident;
        if(active.isEmpty()){
            if(verdict!=DetectionRules.Verdict.ABNORMAL||bad<rules.hysteresis()){mark(tenant,seq,verdict==DetectionRules.Verdict.HEALTHY?"HEALTHY":"HYSTERESIS",null);return;}
            if(db.jdbc.queryForObject("select count(*) from monitor_incidents where tenant_id=? and active",Integer.class,tenant)>=100){mark(tenant,seq,"INCIDENT_BUDGET",null);return;}
            var recent=db.jdbc.queryForList("select rules::text from monitor_incidents where tenant_id=? and scope_key=? and closed_at>now()-(? * interval '1 second') order by closed_at desc limit 1",String.class,tenant,scope,rules.cooldownSeconds());if(!recent.isEmpty()&&((List<?>)Json.decode(recent.getFirst())).contains(e.rule_id())){mark(tenant,seq,"COOLDOWN",null);return;}
            var item=DeterministicInvestigator.analyze(new IncidentRequest("SIMULATED monitored "+e.rule_id()+" on "+e.resource(),e.excerpt(),null,e.environment(),tenant),tenant);item.incident_id=id();incident=item.incident_id;item.severity=severity(e);item.affected_entities=List.of(e.resource());workflows.save(tenant,item);String fingerprint=hash(List.of(scope,time.getEpochSecond()/rules.windowSeconds()));db.jdbc.update("insert into monitor_incidents(tenant_id,id,scope_key,fingerprint,graph_id,graph_revision,environment,cluster_id,source_mode) values(?,?,?,?,?,?,?,?,?)",tenant,incident,scope,fingerprint,e.graph_id(),e.graph_revision(),e.environment(),e.cluster_id(),e.source_mode());workflows.audit(tenant,"monitor_incident_opened",incident,"system.monitor",obj("fingerprint",fingerprint,"impact",e.impact(),"source_mode",e.source_mode()));
            var prior=db.jdbc.queryForList("select payload::text from monitor_events where tenant_id=? and seq<? and state in ('HYSTERESIS','HEALTHY') order by seq desc limit 200",String.class,tenant,seq);for(String text:prior){var old=Json.decode(text,MonitoringContracts.SignalReceived.class);if(old.graph_id().equals(e.graph_id())&&old.graph_revision()==e.graph_revision()&&scope(old,graph).equals(scope)&&Duration.between(Instant.parse(old.observed_at()),time).abs().toSeconds()<=rules.windowSeconds())observe(tenant,incident,old,graph);}
        }else{incident=active.getFirst().get("id").toString();if(e.graph_revision()<((Number)active.getFirst().get("graph_revision")).intValue()){mark(tenant,seq,"OLD_GRAPH_REVISION",incident);return;}}
        if(!observe(tenant,incident,e,graph)){mark(tenant,seq,"EVIDENCE_BUDGET",incident);return;}var observations=correlations.observations(tenant,incident);Instant watermark=observations.stream().map(o->Instant.parse(o.observed_at())).max(Comparator.naturalOrder()).orElse(time);var windowed=observations.stream().filter(o->!Instant.parse(o.observed_at()).isBefore(watermark.minusSeconds(rules.windowSeconds()))).toList();var result=new CorrelationEngine().investigate(tenant,incident,graph,windowed);db.jdbc.update("update monitor_incidents set result=?::jsonb,graph_revision=?,updated_at=now(),rules=(select coalesce(jsonb_agg(distinct x),'[]') from jsonb_array_elements(rules || ?::jsonb) x) where tenant_id=? and id=?",encode(result),e.graph_revision(),encode(List.of(e.rule_id())),tenant,incident);
        var item=workflows.incident(tenant,incident);if(severity(e).ordinal()<item.severity.ordinal()){item.severity=severity(e);workflows.save(tenant,item);workflows.audit(tenant,"monitor_severity_escalated",incident,"system.monitor",obj("severity",item.severity,"measured_impact",e.impact()));}
        mark(tenant,seq,"PROCESSED",incident);queue(tenant,incident,result);}
    private Severity severity(MonitoringContracts.SignalReceived e){var impact=e.impact();return impact!=null&&impact.criticality()!=null&&impact.criticality()>=4?Severity.P1:impact!=null&&impact.datasets()!=null&&impact.datasets()>1?Severity.P2:Severity.P3;}
    private boolean observe(String tenant,String incident,MonitoringContracts.SignalReceived e,DependencyGraph graph){if(db.jdbc.queryForObject("select count(*) from correlation_observations where tenant_id=? and incident_id=?",Integer.class,tenant,incident)>=1000)return false;var verdict=rules.evaluate(e,graph.metadata_mode());if(verdict!=DetectionRules.Verdict.ABNORMAL&&verdict!=DetectionRules.Verdict.HEALTHY)return false;var o=new CorrelationEngine.Observation("MON-"+hash(e.event_id()).substring(0,40),tenant,incident,e.resource(),rules.rule(e.rule_id()).signal(),verdict==DetectionRules.Verdict.HEALTHY?CorrelationEngine.State.HEALTHY:CorrelationEngine.State.ABNORMAL,e.observed_at(),e.source_mode(),0.8,"rules-v1:"+e.rule_id());correlations.registerMonitoringSimulation(tenant,graph,List.of(o));return true;}
    private void queue(String tenant,String incident,CorrelationEngine.Investigation result){if(result.candidate_causes().isEmpty())return;String origin=result.candidate_causes().getFirst().entity_id()+":"+result.candidate_causes().getFirst().signal();String key=hash(List.of(incident,origin));int recent=db.jdbc.queryForObject("select count(*) from monitor_outbox where tenant_id=? and created_at>now()-interval '1 minute'",Integer.class,tenant);if(recent>=10)return;for(String kind:List.of("INVESTIGATE","NOTIFY")){if(db.jdbc.queryForObject("select count(*) from monitor_outbox where tenant_id=? and incident_id=? and kind=?",Integer.class,tenant,incident,kind)>=2)continue;db.jdbc.update("insert into monitor_outbox(tenant_id,id,incident_id,kind) values(?,?,?,?) on conflict do nothing",tenant,key+kind,incident,kind);}}
    public void dispatch(String tenant){if(!suppressed(tenant))db.write(tenant,()->{db.jdbc.update("update monitor_outbox set state='PENDING',detail='Suppression expired or cleared' where tenant_id=? and kind='NOTIFY' and state='SUPPRESSED'",tenant);return null;});for(var row:db.jdbc.queryForList("select id,incident_id,kind from monitor_outbox where tenant_id=? and state='PENDING' order by created_at limit 10",tenant)){
        String key=row.get("id").toString(),incident=row.get("incident_id").toString();if(row.get("kind").equals("NOTIFY")&&suppressed(tenant)){db.write(tenant,()->{db.jdbc.update("update monitor_outbox set state='SUPPRESSED',detail='Operator bounded suppression' where tenant_id=? and id=? and state='PENDING'",tenant,key);return null;});continue;}if(row.get("kind").equals("NOTIFY")){db.write(tenant,()->{if(env.getProperty("investinator.monitor.fake-notification-outage",Boolean.class,false)){db.jdbc.update("update monitor_outbox set attempts=attempts+1,state=case when attempts>=2 then 'MANUAL_INTERVENTION' else 'PENDING' end,detail='LOCAL_FAKE_UNAVAILABLE' where tenant_id=? and id=? and state='PENDING'",tenant,key);return null;}int delivered=db.jdbc.update("insert into monitor_deliveries(tenant_id,outbox_id,destination) values(?,?,'LOCAL_FAKE') on conflict do nothing",tenant,key);if(delivered==1&&env.getProperty("investinator.monitor.console-enabled",Boolean.class,false))org.slf4j.LoggerFactory.getLogger(getClass()).info("SIMULATED notification incident={} delivery={}",incident,key);db.jdbc.update("update monitor_outbox set state='SIMULATED_DELIVERY',attempts=attempts+1 where tenant_id=? and id=? and state='PENDING'",tenant,key);return null;});}
        else{String status=chat.configurationStatus().equals("NOT_CONFIGURED")?"NOT_CONFIGURED":"AWAITING_OPERATOR_BUDGET";db.write(tenant,()->{db.jdbc.update("update monitor_outbox set state=?,detail='Operator must explicitly invoke bounded read-only chat; no automatic spend' where tenant_id=? and id=? and state='PENDING'",status,tenant,key);return null;});}
    }}
    public Map<String,Object> incident(String tenant,String id){var rows=db.jdbc.queryForList("select lifecycle,fingerprint,result::text,source_mode,active from monitor_incidents where tenant_id=? and id=?",tenant,id);if(rows.isEmpty())throw new ApiFailure(404,"Monitored incident not found");var row=new LinkedHashMap<>(rows.getFirst());row.put("result",Json.decode(row.get("result").toString()));return row;}
    public Map<String,Object> transition(String tenant,String id,MonitoringContracts.Lifecycle target,boolean verified){return transition(tenant,id,target,verified,"demo.monitor_operator");}
    public Map<String,Object> transitionForRemediation(String tenant,String id,MonitoringContracts.Lifecycle target,boolean verified){return transition(tenant,id,target,verified,"system.remediation_policy");}
    private Map<String,Object> transition(String tenant,String id,MonitoringContracts.Lifecycle target,boolean verified,String actor){return db.write(tenant,()->{var row=incident(tenant,id);var from=MonitoringContracts.Lifecycle.valueOf(row.get("lifecycle").toString());var allowed=switch(from){case NEW->Set.of(MonitoringContracts.Lifecycle.TRIAGED,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);case TRIAGED->Set.of(MonitoringContracts.Lifecycle.INVESTIGATING,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);case INVESTIGATING->Set.of(MonitoringContracts.Lifecycle.AWAITING_APPROVAL,MonitoringContracts.Lifecycle.MITIGATING,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);case AWAITING_APPROVAL->Set.of(MonitoringContracts.Lifecycle.MITIGATING,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);case MITIGATING->Set.of(MonitoringContracts.Lifecycle.VERIFYING,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);case VERIFYING->Set.of(MonitoringContracts.Lifecycle.RESOLVED,MonitoringContracts.Lifecycle.MITIGATING,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED);default->Set.<MonitoringContracts.Lifecycle>of();};if(!allowed.contains(target)||target==MonitoringContracts.Lifecycle.RESOLVED&&!verified)throw new ApiFailure(409,"Illegal or unverified lifecycle transition");boolean terminal=Set.of(MonitoringContracts.Lifecycle.RESOLVED,MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED).contains(target);db.jdbc.update("update monitor_incidents set lifecycle=?,active=?,closed_at=case when ? then now() else null end,updated_at=now() where tenant_id=? and id=?",target.name(),!terminal,terminal,tenant,id);var old=workflows.incident(tenant,id);old.status=target==MonitoringContracts.Lifecycle.RESOLVED?Lifecycle.resolved:target==MonitoringContracts.Lifecycle.CLOSED_UNRESOLVED?Lifecycle.closed_unresolved:Lifecycle.investigating;workflows.save(tenant,old);workflows.audit(tenant,"monitor_lifecycle",id,actor,obj("from",from,"to",target,"independently_verified",verified));return incident(tenant,id);});}
}
